do $patch$ declare body text; begin select pg_get_functiondef('public.validate_booking_update()'::regprocedure) into body; if position('if auth.uid()=old.client_id and new.status not in' in body)=0 then raise exception 'Unexpected booking guard'; end if; body:=replace(body,'if auth.uid()=old.client_id and new.status not in','if auth.uid()=old.client_id and auth.uid() is distinct from old.provider_id and new.status not in'); execute body; end $patch$;
